export function parseLog(raw) {
  const lines = raw.replace(/\r\n?/g, '\n').split('\n');
  const blocks = [];
  let buffer = null;
  let currentSpeaker = '';
  let hasBlankLine = false;

  const flush = () => {
    if (!buffer) return;
    const text = buffer.text.replace(/^\n+|\n+$/g, '');
    if (text.trim()) blocks.push({...buffer, text, id: uid()});
    buffer = null;
  };

  for (const line of lines) {
    if (!line.trim()) {
      hasBlankLine = true;
      continue;
    }

    if (hasBlankLine) {
      flush();
      hasBlankLine = false;
    }

    const speaker = getSpeaker(line);

    if (speaker) {
      flush();
      currentSpeaker = speaker.speaker;
      buffer = {type: 'speaker', speaker: currentSpeaker, text: speaker.text};
      continue;
    }

    if (headingPattern.test(line)) {
      flush();
      currentSpeaker = '';
      buffer = {type: 'heading', speaker: '', text: line};
      continue;
    }

    if (!buffer) {
      const isQuote = /^["“「『]/.test(line.trim());
      const type = isQuote && currentSpeaker ? 'speaker' : 'narration';
      buffer = {type, speaker: type === 'speaker' ? currentSpeaker : '', text: line};
    } else {
      buffer.text += `\n${line}`;
    }
  }

  flush();
  return blocks;
}

export function speakersOf(blocks) {
  return [...new Set(
      blocks.filter(b => b.type === 'speaker' && b.speaker.trim())
          .map(b => b.speaker.trim())
  )];
}
